"""Lay students out in seating rows."""

def _sort_key(student):
    return (student.last_name.lower(), student.first_name.lower())

def _chunks(items, size):
    starts = range(0, len(items), size)
    return [items[i:i + size] for i in starts]

def _row_line(number, row):
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

# ---
def seat_rows(students, seats_per_row):
    """Return one "Row N: ..." line per row, by last name."""
    if seats_per_row <= 0 or not students:
        raise ValueError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, seats_per_row)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]

