# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seat_rows

def make(last, first):
    return Student(last + first, last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbott", "Cy")
        ]

    def test_sorted_and_grouped(self):
        self.assertEqual(seat_rows(self.students, 2), [
            "Row 1: Abbott, Cy | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row(self):
        lines = seat_rows(self.students, 5)
        self.assertEqual(len(lines), 1)

    def test_first_name_breaks_ties(self):
        pair = [make("Lee", "Zed"), make("Lee", "Amy")]
        line = seat_rows(pair, 2)[0]
        self.assertEqual(line, "Row 1: Lee, Amy | Lee, Zed")

    def test_bad_seat_counts(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(self.students, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
